SELECT AVG(Age) AS Average_Age, MIN(Age) AS Min_Age, MAX(Age) AS Max_Age
FROM singer
WHERE Country = 'France';

SELECT AVG(Age) AS Average_Age, MIN(Age) AS Minimum_Age, MAX(Age) AS Maximum_Age
FROM singer
WHERE Country = 'France';

SELECT s.Song_Name
FROM singer s
WHERE s.Age > (SELECT AVG(Age) FROM singer);

SELECT s.Song_Name
FROM singer s
WHERE s.Age > (SELECT AVG(Age) FROM singer);

SELECT pet_type, MAX(weight) AS max_weight
FROM Pets
GROUP BY pet_type;

SELECT COUNT(PetID) FROM Pets WHERE PetType = 'Dog' AND StuID IN (
    SELECT StuID FROM Student WHERE Sex = 'F'
)

SELECT s.Major, s.Age
FROM Student s
WHERE s.StuID NOT IN (SELECT hp.StuID FROM Has_Pet hp JOIN Pets p ON hp.PetID = p.PetID WHERE p.PetType = 'Cat');

SELECT pet_type, AVG(pet_age) AS avg_age, MAX(pet_age) AS max_age
FROM Pets
GROUP BY pet_type;

SELECT PetType, AVG(Weight) AS AverageWeight
FROM Pets
GROUP BY PetType;

SELECT PetType, AVG(weight) AS AverageWeight
FROM Pets
GROUP BY PetType;

SELECT s.Fname, s.Age
FROM Student s
JOIN Has_Pet hp ON s.StuID = hp.StuID;

SELECT DISTINCT s.Fname, s.Age
FROM Student s
JOIN Has_Pet hp ON s.StuID = hp.StuID;

SELECT StuID, COUNT(PetID) AS num_pets
FROM Has_Pet
GROUP BY StuID;

SELECT StuID, COUNT(PetID) AS PetCount
FROM Has_Pet
GROUP BY StuID;

SELECT AVG(T1.Age) AS AverageAge
FROM Student AS T1
WHERE T1.StuID NOT IN (SELECT StuID FROM Has_Pet);

SELECT Model FROM car_names WHERE MakeId IN (
    SELECT MakeId FROM cars_data WHERE Weight < (
        SELECT AVG(Weight) FROM cars_data
    )
)

SELECT car_names.Make, car_names.Model
FROM car_names
JOIN model_list ON car_names.Model = model_list.Model;

SELECT Year, AVG(Weight) AS AverageWeight
FROM cars_data
GROUP BY Year;

SELECT AVG(Weight) AS AverageWeight, Year AS Year
FROM cars_data
GROUP BY Year;

SELECT AVG(Horsepower) AS AverageHorsepower
FROM cars_data
WHERE Year < 1980;

SELECT COUNT(Id) 
FROM cars_data 
WHERE Accelerate > (SELECT MAX(Accelerate) FROM cars_data);

SELECT COUNT(*) 
FROM cars_data 
WHERE Accelerate > (SELECT MAX(Accelerate) FROM cars_data);

SELECT COUNT(*) FROM (
    SELECT continent FROM countries GROUP BY continent HAVING COUNT(countryid) > 2
)

SELECT Id, Maker FROM car_makers WHERE Id IN (
    SELECT Maker FROM model_list GROUP BY Maker HAVING COUNT(*) > 3
) INTERSECT
SELECT Id, Maker FROM car_makers WHERE Id IN (
    SELECT Maker FROM model_list GROUP BY Maker HAVING COUNT(*) >= 2
);
